const b = $input.first().json.body || $input.first().json;
const units = Number(b.units) || 12;
const ask = Number(b.ask) || units * 145000;
const offer = Math.round(ask * 0.982);
const gpr = units * 1450 * 12;
const egi = gpr * 0.95;
const expenses = egi * 0.38;
const noi = egi - expenses;
const cap = (noi / offer) * 100;
const score = Math.round(50 + Math.min(40, cap * 5));
const rec = score >= 78 ? 'pursue' : score >= 62 ? 'watch' : 'pass';
return [{ json: { runId: b.runId, callbackUrl: b.callbackUrl, result: {
  title: b.query,
  subtitle: units + '-unit garden / small multifamily',
  investorScore: score,
  recommendation: rec,
  summary: `Cap ${cap.toFixed(2)}% at $${offer.toLocaleString()}. Attach a rent roll HTTP node before this Code step for live T12.`,
  metrics: [
    { label: 'Offer', value: '$' + offer.toLocaleString() },
    { label: 'Units', value: String(units) },
    { label: 'NOI', value: '$' + Math.round(noi).toLocaleString() },
    { label: 'Cap rate', value: cap.toFixed(2) + '%' },
    { label: '$ / unit', value: '$' + Math.round(offer / units).toLocaleString() }
  ],
  sections: [{ heading: 'T12', body: 'n8n should parse an uploaded rent roll and overwrite GPR / expenses before callback.' }]
} } }];
